const appliedForward = applyKitDiff(kitOriginal, change.forward);
// [DEBUG] Check types,designs,authors equality individually
const { areTypesEqual: areTypesEq, areDesignsEqual: areDesignsEq, areAuthorsEqual: areAuthorsEq } = (() => {
  const normalizeArray = <T>(arr: T[] | T | undefined | null): T[] => { if (!arr) return []; if (Array.isArray(arr)) return arr; return [arr as T]; };
  const normalizeValue = (v: any): any => (v === null || v === "" || v === undefined ? undefined : v);
  return {
    areTypesEqual: (aa: any[], bb: any[]): string => {
      if (aa.length !== bb.length) return `type count mismatch: ${aa.length} vs ${bb.length}`;
      for (const ta of aa) {
        const tb = bb.find((t: any) => t.guid === ta.guid);
        if (!tb) return `type guid ${ta.guid} (${ta.name}) not found in expected`;
        if (ta.name !== tb.name) return `type ${ta.guid}: name ${ta.name} vs ${tb.name}`;
        if (normalizeValue(ta.description) !== normalizeValue(tb.description)) return `type ${ta.guid}: description mismatch`;
        if (normalizeValue(ta.icon) !== normalizeValue(tb.icon)) return `type ${ta.guid}: icon mismatch`;
        if (normalizeValue(ta.image) !== normalizeValue(tb.image)) return `type ${ta.guid}: image mismatch`;
        if (ta.stock !== tb.stock) return `type ${ta.guid}: stock ${ta.stock} vs ${tb.stock}`;
        const modelsA = normalizeArray(ta.models);
        const modelsB = normalizeArray(tb.models);
        if (modelsA.length !== modelsB.length) return `type ${ta.guid} (${ta.name}): models count ${modelsA.length} vs ${modelsB.length}`;
        for (const ma of modelsA) {
          const mb = modelsB.find((m: any) => m.guid === ma.guid);
          if (!mb) return `type ${ta.guid}: model ${ma.guid} (${ma.name}) not found`;
        }
        const connsA = normalizeArray(ta.connectors);
        const connsB = normalizeArray(tb.connectors);
        if (connsA.length !== connsB.length) return `type ${ta.guid} (${ta.name}): connectors count ${connsA.length} vs ${connsB.length}`;
        for (const ca of connsA) {
          const cb = connsB.find((c: any) => c.guid === ca.guid);
          if (!cb) return `type ${ta.guid}: connector ${ca.guid} (${ca.name}) not found`;
          if (normalizeValue(ca.description) !== normalizeValue(cb.description)) return `type ${ta.guid}: connector ${ca.guid} description mismatch: "${ca.description}" vs "${cb.description}"`;
        }
      }
      return 'OK';
    },
    areDesignsEqual: (aa: any[], bb: any[]): string => {
      if (aa.length !== bb.length) return `design count mismatch: ${aa.length} vs ${bb.length}`;
      for (const da of aa) {
        const db = bb.find((d: any) => d.guid === da.guid);
        if (!db) return `design guid ${da.guid} not found`;
        if (da.name !== db.name) return `design ${da.guid}: name mismatch`;
        const pA = normalizeArray(da.pieces);
        const pB = normalizeArray(db.pieces);
        if (pA.length !== pB.length) return `design ${da.guid}: pieces count ${pA.length} vs ${pB.length}`;
        for (const pa of pA) {
          const pb = pB.find((p: any) => p.guid === pa.guid);
          if (!pb) return `design ${da.guid}: piece ${pa.guid} not found`;
          if (normalizeValue(pa.name) !== normalizeValue(pb.name)) return `design ${da.guid}: piece ${pa.guid} name mismatch: "${pa.name}" vs "${pb.name}"`;
        }
        const cA = normalizeArray(da.connections);
        const cB = normalizeArray(db.connections);
        if (cA.length !== cB.length) return `design ${da.guid}: connections count ${cA.length} vs ${cB.length}`;
      }
      return 'OK';
    },
    areAuthorsEqual: (aa: any[], bb: any[]): string => {
      if (aa.length !== bb.length) return `author count: ${aa.length} vs ${bb.length}`;
      for (const a of aa) {
        const b = bb.find((x: any) => x.guid === a.guid);
        if (!b) return `author guid ${a.guid} not found`;
        if (a.name !== b.name) return `author ${a.guid}: name "${a.name}" vs "${b.name}"`;
        if (a.email !== b.email) return `author ${a.guid}: email "${a.email}" vs "${b.email}"`;
      }
      return 'OK';
    }
  };
})();
