console.log(`[DEBUG] designs check: ${areDesignsEq(appliedForward.designs || [], kitDiffed.designs || [])}`);
console.log(`[DEBUG] authors check: ${areAuthorsEq(appliedForward.authors || [], kitDiffed.authors || [])}`);
expect(areKitsEqual(appliedForward, kitDiffed)).toBe(true);

