  for (const ca of na(da.connections)) {
    const cb = na(db.connections).find((c: any) => c.guid === ca.guid);
    if (!cb) { console.log(`[DEBUG] design ${da.guid}: connection ${ca.guid} not found`); continue; }
  }
}
