console.log(`[DEBUG] About to exportKit`);
// [DEBUG] Monkey-patch sql.js to find the undefined binding
const SQL = (await import('sql.js')).default;
const origInit = SQL;
const sqlInstance = await SQL();
const OrigDatabase = sqlInstance.Database;
const origDb = new OrigDatabase();
const origRun = origDb.run.bind(origDb);
// We can't easily monkey-patch, just catch and inspect:
try {
  const exportedZip = await exportKit(kit);
  console.log(`[DEBUG] exportKit succeeded`);
  const { kit: reKit } = await importKit(exportedZip);
  console.log(`[DEBUG] re-importKit succeeded`);
  expect(areKitsEqual(kit, reKit)).toBe(true);
} catch (e: any) {
  // [DEBUG] Scan kit JSON for undefined patterns
  const scanForUndefined = (obj: any, path: string) => {
    if (obj === undefined) { console.log(`[DEBUG] UNDEFINED at ${path}`); return; }
    if (obj === null || typeof obj !== 'object') return;
    if (Array.isArray(obj)) { obj.forEach((item, i) => scanForUndefined(item, `${path}[${i}]`)); return; }
    for (const [k, v] of Object.entries(obj)) {
      scanForUndefined(v, `${path}.${k}`);
    }
  };
  // Check all design pieces for the issue
  for (const design of kit.designs || []) {
    for (const piece of design.pieces || []) {
      if (piece.plane) {
        if (piece.plane.origin?.x === undefined) console.log(`[DEBUG] piece ${piece.guid} plane.origin.x is undefined`);
        if (piece.plane.origin?.y === undefined) console.log(`[DEBUG] piece ${piece.guid} plane.origin.y is undefined`);
        if (piece.plane.origin?.z === undefined) console.log(`[DEBUG] piece ${piece.guid} plane.origin.z is undefined`);
      }
    }
  }
  // Actually, the MetabolismKit has designs with parents (nested). The test filters them out for the Change test but not for Roundtrip.
  // Let me check for all types with undefined properties
  for (const type of kit.types || []) {
    for (const connector of type.connectors || []) {
      if (connector.t === undefined) console.log(`[DEBUG] type ${type.name} connector ${connector.guid} has t=undefined`);
      if (connector.point === undefined) console.log(`[DEBUG] type ${type.name} connector ${connector.guid} has point=undefined`);
    }
  }
  throw e;
}

