  console.log(`[DEBUG] importKit from zip succeeded`);
  expect(areKitsEqual(kit, zipKit)).toBe(true);

  console.log(`[DEBUG] About to exportKit`);
  // [DEBUG] Check specific values that kitToSqlite computes
  for (const design of kit.designs || []) {
    for (const prop of design.props || []) {
      const val = parseFloat(prop.value);
      if (isNaN(val)) console.log(`[DEBUG] design ${design.guid} prop ${prop.guid}: parseFloat("${prop.value}")=NaN`);
      if (prop.quality?.guid === undefined) console.log(`[DEBUG] design ${design.guid} prop ${prop.guid}: quality.guid is undefined`);
    }
    for (const piece of design.pieces || []) {
      for (const prop of piece.props || []) {
        if (prop.quality?.guid === undefined) console.log(`[DEBUG] piece ${piece.guid} prop ${prop.guid}: quality.guid is undefined`);
        if (prop.value === undefined) console.log(`[DEBUG] piece ${piece.guid} prop ${prop.guid}: value is undefined`);
      }
    }
    for (const conn of design.connections || []) {
      if (conn.connected?.connector === undefined) console.log(`[DEBUG] conn ${conn.guid}: connected.connector is undefined`);
      if (conn.connecting?.connector === undefined) console.log(`[DEBUG] conn ${conn.guid}: connecting.connector is undefined`);
      if (conn.connected?.piece?.guid === undefined) console.log(`[DEBUG] conn ${conn.guid}: connected.piece.guid is undefined`);
      if (conn.connecting?.piece?.guid === undefined) console.log(`[DEBUG] conn ${conn.guid}: connecting.piece.guid is undefined`);
    }
  }
  for (const type of kit.types || []) {
    for (const connector of type.connectors || []) {
      for (const prop of connector.props || []) {
        if (prop.quality?.guid === undefined) console.log(`[DEBUG] type ${type.name} connector ${connector.guid} prop ${prop.guid}: quality.guid undefined`);
        if (prop.value === undefined) console.log(`[DEBUG] type ${type.name} connector ${connector.guid} prop ${prop.guid}: value undefined`);
      }
    }
  }
  const exportedZip = await exportKit(kit);
  console.log(`[DEBUG] exportKit succeeded`);
  const { kit: reKit } = await importKit(exportedZip);
  console.log(`[DEBUG] re-importKit succeeded`);
  expect(areKitsEqual(kit, reKit)).toBe(true);
});

