const exportedZip = await exportKit(kit);
const { kit: reKit } = await importKit(exportedZip);
// [DEBUG] Find which areKitsEqual check fails
const _normalizeArray = <T,>(arr: T[] | T | undefined | null): T[] => {
  if (!arr) return [];
  if (Array.isArray(arr)) return arr;
  return [arr as T];
};
const checks = [
  ['guid', kit.guid === reKit.guid],
  ['name', kit.name === reKit.name],
  ['types.length', _normalizeArray(kit.types).length === _normalizeArray(reKit.types).length],
  ['designs.length', _normalizeArray(kit.designs).length === _normalizeArray(reKit.designs).length],
  ['ports.length', _normalizeArray(kit.ports).length === _normalizeArray(reKit.ports).length],
  ['qualities.length', _normalizeArray(kit.qualities).length === _normalizeArray(reKit.qualities).length],
  ['files.length', _normalizeArray(kit.files).length === _normalizeArray(reKit.files).length],
  ['folders.length', _normalizeArray(kit.folders).length === _normalizeArray(reKit.folders).length],
  ['authors.length', _normalizeArray(kit.authors).length === _normalizeArray(reKit.authors).length],
];
for (const [name, pass] of checks) {
  if (!pass) console.log(`[DEBUG] CHECK FAILED: ${name} kit=${JSON.stringify((kit as any)[name.split('.')[0]]?.length ?? (kit as any)[name.split('.')[0]])} reKit=${JSON.stringify((reKit as any)[name.split('.')[0]]?.length ?? (reKit as any)[name.split('.')[0]])}`);
}
// [DEBUG] Check each type individually
for (const typeA of _normalizeArray(kit.types)) {
  const typeB = _normalizeArray(reKit.types).find((t: any) => t.guid === typeA.guid);
  if (!typeB) { console.log(`[DEBUG] Type ${typeA.guid} (${typeA.name}) not found in reKit`); continue; }
  if (typeA.stock !== typeB.stock) console.log(`[DEBUG] Type ${typeA.name}: stock ${typeA.stock} vs ${typeB.stock}`);
}
// [DEBUG] Check each design individually  
for (const designA of _normalizeArray(kit.designs)) {
  const designB = _normalizeArray(reKit.designs).find((d: any) => d.guid === designA.guid && ((!d.parent && !designA.parent) || (d.parent?.guid === designA.parent?.guid)));
  if (!designB) { console.log(`[DEBUG] Design ${designA.guid} (${designA.name}) parent=${designA.parent?.guid} not found in reKit`); continue; }
}
expect(areKitsEqual(kit, reKit)).toBe(true);

